import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Stage 1 · Durable Kernel & MVP","description":"Hearth Stage 1 development module: walking skeleton, first Codex slice, MVP-1, side-effect safety, recovery hardening, and Stage 1 release.","frontmatter":{"title":"Stage 1 · Durable Kernel & MVP","description":"Hearth Stage 1 development module: walking skeleton, first Codex slice, MVP-1, side-effect safety, recovery hardening, and Stage 1 release.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-1.md","filePath":"en/delivery/stage-1.md","lastUpdated":1793752688000}'),o={name:"en/delivery/stage-1.md"};function s(n,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<p class="eyebrow">MODULE 1 / 7</p><h1 id="stage-1-·-durable-kernel-mvp" tabindex="-1">Stage 1 · Durable Kernel &amp; MVP <a class="header-anchor" href="#stage-1-·-durable-kernel-mvp" aria-label="Permalink to &quot;Stage 1 · Durable Kernel &amp; MVP&quot;">​</a></h1><p class="lead">Move from prototype to a daily-usable local product. The order is fixed: real short loop → first Codex slice → MVP closeout → side-effect safety → second task family → recovery and release.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>The 12 tasks, prototype, contracts, evaluation, and security baseline from Stage 0 are usable.</li><li>The first task family is chosen. Research/document work is the default; if the first user mainly needs coding tasks, replace the wedge but keep the same vertical structure.</li><li>Web is the real product entry point. CLI, logs, or scripts alone are not sufficient.</li></ul><h2 id="development-steps" tabindex="-1">Development Steps <a class="header-anchor" href="#development-steps" aria-label="Permalink to &quot;Development Steps&quot;">​</a></h2><ol><li><strong>Deliver the walking skeleton.</strong> Start <code>hearthd</code> with SQLite WAL, a minimal Event Log, Task/Run state machine, projections, fake executor, Web task list/detail/create, and SSE.</li><li><strong>Connect the first real Codex slice.</strong> Implement the Codex adapter, health check, one-shot workspace, Task Pack, structured output, Artifact, citation/file verification, event projection, and Token/latency capture.</li><li><strong>Close MVP-1.</strong> Complete create, view, cancel, retry, approval drill, artifact retrieval, failure recovery, and budget stop as one real narrow task loop.</li><li><strong>Add the side-effect safety skeleton.</strong> Implement Effect Preview, Mandate, Approval, outbox, idempotency key, Receipt, undo/compensation drills, and a single-writer lease.</li><li><strong>Add a second task family and harden the kernel.</strong> Use it to validate routing, failure classes, budgets, concurrency, duplicate delivery, crash recovery, and projection consistency.</li><li><strong>Complete the Stage 1 release.</strong> Run 10 real tasks, compare manual and direct-Codex baselines, fix high-frequency failures, and add install, backup, upgrade, export, security, and evaluation evidence.</li></ol><h2 id="increment-breakdown" tabindex="-1">Increment Breakdown <a class="header-anchor" href="#increment-breakdown" aria-label="Permalink to &quot;Increment Breakdown&quot;">​</a></h2><p>Each increment now has four layers: outcome and gate → four work packages → engineering map and interfaces → acceptance rehearsal. Packages can be split across developers, but merge in dependency order; completing one package does not complete the increment.</p><table tabindex="0"><thead><tr><th>Increment</th><th>User-visible outcome</th><th>Completion evidence</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/delivery/stage-1/d1-1.html">D1.1</a> Runnable walking skeleton</td><td>Create a Web task; state survives refresh and restart</td><td><code>hearthd</code> + SQLite + Event Log + fake executor + SSE</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-1/d1-2.html">D1.2</a> First Codex slice</td><td>A report with sources, verification, and cost</td><td>Task Pack, structured Result, Artifact, verifier</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-1/d1-3.html">D1.3</a> MVP closeout</td><td>Create, cancel, retry, approve, retrieve, and recover in the browser</td><td>The MVP-1 user story passes end to end</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-1/d1-4.html">D1.4</a> Side-effect safety skeleton</td><td>External actions have preview, approval, idempotency, and receipt</td><td>outbox, idempotency, Receipt, undo/compensation drill</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-1/d1-5.html">D1.5</a> Second task family and hardening</td><td>A second real task family is dependable and recoverable</td><td>Routing, fault injection, duplicate delivery, recovery tests</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-1/d1-6.html">D1.6</a> Stage 1 release</td><td>Users can install, use, back up, and export independently</td><td>10 real tasks, baseline comparison, security and evaluation report</td></tr></tbody></table><h2 id="where-the-mvp-fits" tabindex="-1">Where the MVP Fits <a class="header-anchor" href="#where-the-mvp-fits" aria-label="Permalink to &quot;Where the MVP Fits&quot;">​</a></h2><p>MVP-1 is the early Stage 1 exit at D1.3, not a Stage 6 product. It may omit email, calendar, GUI, proactivity, and multi-device, but it must include real execution, durable state, Web task cards, artifacts, approval drills, and failure recovery.</p><h2 id="exit-checklist" tabindex="-1">Exit Checklist <a class="header-anchor" href="#exit-checklist" aria-label="Permalink to &quot;Exit Checklist&quot;">​</a></h2><ul><li>[ ] The MVP supports one narrow task family every day in the browser.</li><li>[ ] After a crash, refresh, or restart, tasks recover or explicitly move to human handling.</li><li>[ ] Duplicate delivery and retries do not create duplicate external side effects.</li><li>[ ] Task cards show state, artifacts, cost, and next action; failure reasons are understandable.</li><li>[ ] At least 10 real tasks pass human acceptance; Token and manual-minute baselines exist.</li><li>[ ] Permission boundaries, secret protection, kill switch, backup, and data export work.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Email, calendar, desktop GUI, proactive loops, or multi-device.</li><li>Expanding the number of executors before recovery, approval, and UI completeness are solid.</li><li>Replacing real Codex execution and verification with demo scripts.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Continue to <a href="/hearth-os/en/delivery/stage-2.html">Stage 2 · Personal Operator</a>, starting with read-only connectors for everyday content work.</p>',18)])])}const f=t(o,[["render",s]]);export{u as __pageData,f as default};
